require 'webrick'
require 'json'
require 'ipaddr'
require 'socket'
require 'openssl'

module Fluent
  module RPC
    class Server
      def initialize(endpoint, log)
        bind, port = endpoint.split(':')
        @bind = bind
        @port = port
        @log = log

        @server = WEBrick::HTTPServer.new(
          BindAddress: @bind,
          Port: @port,
          Logger: WEBrick::Log.new(STDERR, WEBrick::Log::FATAL),
          AccessLog: [],
        )
        reset_handler_table
        self.class.collect_rpc_diagnostics(@bind, @port, false)
        @request_count = 0
        @last_error = nil
        @rpc_started = false
        @log.debug "rpc server prepared", bind: bind_for_log, port: port_value
      end

      def mount(path, servlet, *args)
        @server.mount(path, servlet, *args)
        record_handler_path(path, :servlet)
        @log.debug "register #{path} RPC servlet"
      end

      def mount_proc(path, &block)
        kind = self.class.rpc_path_kind(path)
        @server.mount_proc(path) { |req, res|
          begin
            increment_request_count
            log_rpc_request(path, kind)
            code, header, response = block.call(req, res)
          rescue => e
            remember_last_error(e)
            log_handler_failure(path, e)
            code = 500
            header = default_json_headers
            body = self.class.build_rpc_error_payload(e, e.backtrace)
            response = nil
          end

          code = normalize_status(code)
          header = merge_headers(header)
          body = build_body(code, response) if !defined?(body) || body.nil?

          apply_status(res, code)
          apply_headers(res, header)
          apply_body(res, body)
        }
        record_handler_path(path, :proc)
        @log.debug "register #{path} RPC handler"
      end

      def start
        @log.debug "listening RPC http server on #{listen_url}"
        log_listen
        @rpc_started = true
        @thread = Thread.new {
          @server.start
        }
      end

      def shutdown
        log_shutdown
        if server_present?
          @server.shutdown
          @server = nil
        end
        if thread_running?
          @thread.join
          @thread = nil
        end
        @rpc_started = false
      end

      def install_supervisor_handlers(owner, enable_get_dump: false)
        @log.debug "installing supervisor rpc handlers", bind: bind_for_log, port: port_value
        register_interrupt_workers(owner)
        register_kill_workers(owner)
        register_flush_and_kill(owner)
        register_flush_buffers(owner)
        register_config_reload(owner)
        register_config_dump(owner)
        register_graceful_reload(owner)
        register_get_dump(owner) if enable_get_dump
        handler_count
      end

      def register_interrupt_workers(owner)
        @log.debug "rpc handler interruptWorkers"
        mount_proc('/api/processes.interruptWorkers') { |_req, _res|
          @log.debug "fluentd RPC got /api/processes.interruptWorkers request"
          Process.kill :INT, $$
          nil
        }
      end

      def register_kill_workers(owner)
        @log.debug "rpc handler killWorkers"
        mount_proc('/api/processes.killWorkers') { |_req, _res|
          @log.debug "fluentd RPC got /api/processes.killWorkers request"
          Process.kill :TERM, $$
          nil
        }
      end

      def register_flush_and_kill(owner)
        @log.debug "rpc handler flushBuffersAndKillWorkers"
        mount_proc('/api/processes.flushBuffersAndKillWorkers') { |_req, _res|
          @log.debug "fluentd RPC got /api/processes.flushBuffersAndKillWorkers request"
          if Fluent.windows?
            owner.supervisor_sigusr1_handler
            owner.stop(true)
          else
            Process.kill :USR1, $$
            Process.kill :TERM, $$
          end
          nil
        }
      end

      def register_flush_buffers(owner)
        @log.debug "rpc handler flushBuffers"
        mount_proc('/api/plugins.flushBuffers') { |_req, _res|
          @log.debug "fluentd RPC got /api/plugins.flushBuffers request"
          if Fluent.windows?
            owner.supervisor_sigusr1_handler
          else
            Process.kill :USR1, $$
          end
          nil
        }
      end

      def register_config_reload(owner)
        @log.debug "rpc handler config.reload"
        mount_proc('/api/config.reload') { |_req, _res|
          @log.debug "fluentd RPC got /api/config.reload request"
          if Fluent.windows?
            owner.kill_worker
          else
            Process.kill :HUP, $$
          end
          nil
        }
      end

