def remember_last_error(error)
  @last_error = error
  @log.warn "rpc last error remembered", error: last_error_message
  @last_error
end

def last_error_message
  message = @last_error ? @last_error.to_s : nil
  @log.debug "rpc last error", error: message if message
  message
end

def log_rpc_request(path, kind)
  @log.debug "rpc request", path: path, kind: kind, bind: @bind, port: @port
end

def log_handler_failure(path, error)
  @log.warn "failed to handle RPC request", path: path, error: error.to_s

